node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Get current cart
const cart = db.prepare('SELECT * FROM carts WHERE cart_id = ?').get('CART-user_1b350225');
const itemIds = JSON.parse(cart.item_ids_json || '[]');

// Get product price
const prod = db.prepare('SELECT price FROM products WHERE product_id = ?').get('PROD-73FAB4');
const price = prod.price; // 88

// Determine next cart_item_id
const maxCI = db.prepare(\"SELECT cart_item_id FROM cart_items ORDER BY cart_item_id DESC LIMIT 1\").get();
let nextSeq = 1;
if (maxCI) {
  const m = maxCI.cart_item_id.match(/^CI-(\d+)$/);
  if (m) nextSeq = parseInt(m[1]) + 1;
}
const ciId = 'CI-' + String(nextSeq).padStart(4, '0');
console.log('New cart_item_id:', ciId);

// Insert cart item
db.prepare(
  'INSERT INTO cart_items (cart_item_id, cart_id, customer_id, product_id, quantity, gift_wrap, variant_id) VALUES (?,?,?,?,?,?,?)'
).run(ciId, 'CART-user_1b350225', 'user_1b350225', 'PROD-73FAB4', 1, 0, null);

// Update cart
itemIds.push(ciId);
const subtotal = price * 1;  // quantity=1
const total = subtotal; // no discounts, no gift wrap, no shipping yet
db.prepare(
  'UPDATE carts SET item_ids_json=?, subtotal=?, total=? WHERE cart_id=?'
).run(JSON.dumps ? JSON.stringify(itemIds) : JSON.stringify(itemIds), subtotal, total, 'CART-user_1b350225');

// Verify
const updatedCart = db.prepare('SELECT * FROM carts WHERE cart_id = ?').get('CART-user_1b350225');
const newItem = db.prepare('SELECT * FROM cart_items WHERE cart_item_id = ?').get(ciId);
console.log('\nCart item created:', newItem);
console.log('\nUpdated cart:', {
  cart_id: updatedCart.cart_id,
  items: JSON.parse(updatedCart.item_ids_json),
  subtotal: updatedCart.subtotal,
  total: updatedCart.total,
});
"

